void bubbleSort(int a[], int n) {
    for (int i = 0; i < n - 1; i++) {
        int swapped = 0;
        for (int j = 0; j < n - 1 - i; j++) {   /* settled tail is skipped */
            if (a[j] > a[j + 1]) {
                int t = a[j];
                a[j]  = a[j + 1];
                a[j + 1] = t;
                swapped = 1;
            }
        }
        if (!swapped) break;                    /* already sorted, stop early */
    }
}

void merge(int a[], int low, int mid, int high) {
    int temp[high - low + 1];
    int i = low, j = mid + 1, k = 0;

    while (i <= mid && j <= high)            /* take the smaller front item */
        temp[k++] = (a[i] <= a[j]) ? a[i++] : a[j++];   /* '<=' keeps it stable */

    while (i <= mid)  temp[k++] = a[i++];    /* leftovers of the left half  */
    while (j <= high) temp[k++] = a[j++];    /* leftovers of the right half */

    for (i = low, k = 0; i <= high; i++, k++)
        a[i] = temp[k];
}

void mergeSort(int a[], int low, int high) {
    if (low >= high) return;                 /* one element is already sorted */
    int mid = low + (high - low) / 2;
    mergeSort(a, low, mid);
    mergeSort(a, mid + 1, high);
    merge(a, low, mid, high);
}

#define MAX 100

typedef struct {
    int in[MAX],  out[MAX];
    int topIn,    topOut;
} Queue;

void initQueue(Queue *q) { q->topIn = -1; q->topOut = -1; }

void enqueue(Queue *q, int x) {
    q->in[++(q->topIn)] = x;              /* always O(1) */
}

int dequeue(Queue *q) {
    if (q->topOut < 0) {                  /* refill only when outStack is empty */
        while (q->topIn >= 0)
            q->out[++(q->topOut)] = q->in[(q->topIn)--];
    }
    if (q->topOut < 0) return -1;         /* queue is empty */
    return q->out[(q->topOut)--];
}
